-- Di-generate scripts/seed_postgres.py dari crm_customers (1,000 baris)
DROP TABLE IF EXISTS customers_v2;
CREATE TABLE customers_v2 (
    "customer_pk" BIGINT,
    "customer_id" VARCHAR,
    "first_name" VARCHAR,
    "last_name" VARCHAR,
    "email" VARCHAR,
    "phone_number" VARCHAR,
    "gender" VARCHAR,
    "dob" VARCHAR,
    "signup_date" VARCHAR,
    "address" VARCHAR,
    "city" VARCHAR,
    "state" VARCHAR,
    "country" VARCHAR,
    "device_id" VARCHAR,
    "source" VARCHAR,
    "updated_at" VARCHAR
);

